const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a zonal geometry for the specified latitude band.
  const geometry = ee.Geometry.Polygon(
    [[[-180, -56], [180, -56], [180, -68], [-180, -68], [-180, -56]]], null, false
  );
  const startDate = '2016-01-13';
  const endDate = '2016-01-14';

  // 2. Data Acquisition & Check
  // MODIS Aqua Ocean Color provides daily global chlorophyll-a concentration.
  let collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(startDate, endDate)
    .select('chlor_a');

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('No MODIS Ocean Color images found for Jan 13, 2016.');
    console.log('A'); // Technically no bloom was visible in the data, but it's a data gap, not a 'No'
    return;
  }

  // Create a single mosaic from the day's data.
  const image = collection.mosaic().clip(geometry);

  // 3. Processing: Check for valid pixels
  // Define a reducer to count total valid pixels and pixels indicating a bloom.
  // A bloom is often characterized by chlor_a > 1.0 mg/m^3.
  const bloomThreshold = 1.0;
  const bloomImage = image.gte(bloomThreshold);

  const reducers = ee.Reducer.count().combine({
    reducer2: ee.Reducer.sum(),
    sharedInputs: true
  });

  const statsImage = image.addBands(bloomImage);

  // Use a coarse scale appropriate for a global dataset and large area.
  const scale = 4000;
  const stats = statsImage.reduceRegion({
    reducer: reducers,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const totalPixels = ee.Number(stats.get('chlor_a_count')).getInfo();
  const bloomPixels = ee.Number(stats.get('chlor_a_sum')).getInfo();

  console.log(`Date: ${startDate}`);
  console.log(`Total Ocean Pixels (56-68S): ${totalPixels}`);

  if (totalPixels === 0) {
    console.log('No valid ocean pixels found in the specified latitude band for this date.');
    console.log('C2');
    return;
  }

  if (bloomPixels === null) {
      console.log('Could not calculate bloom pixel count.');
      console.log('C3');
      return;
  }

  // 4. Calculation & Validation
  const bloomPercentage = (bloomPixels / totalPixels) * 100;

  console.log(`Bloom Pixels (chlor_a > ${bloomThreshold} mg/m^3): ${bloomPixels}`);
  console.log(`Percentage of area in bloom: ${bloomPercentage.toFixed(2)}%`);

  // A significant bloom is present if a non-trivial number of pixels show high chlorophyll.
  if (bloomPixels > 1000) { // Using a threshold of >1000 pixels to confirm a widespread event
    console.log('Evidence of a widespread phytoplankton bloom was found.');
    console.log('A');
  } else {
    console.log('No significant phytoplankton bloom was detected.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
